import sys

class Solution:

	def maxSum(self, w, x, b, n):
		max_so_far = -sys.maxsize
		max_current = 0
		i = 0
		j = 0
		s = 0
		if n == 0:
			return w
		for cur in range(len(w)):
			new_asc = ord(w[cur])
			if w[cur] in x:
				new_asc = b[x.index(w[cur])]
			max_current += new_asc
			if max_so_far < max_current:
				max_so_far = max_current
				i = s
				j = cur
			if max_current < 0:
				max_current = 0
				s = cur + 1
		return w[i:j + 1]
